//! CLI reference page, walked from clap's command tree.

use std::fmt::Write as _;

use clap::{Arg, CommandFactory};
use helia_cli::Cli;

/// Markdown for `reference/cli.md`.
pub fn render() -> String {
    let mut root = Cli::command();
    root.build();
    let mut out = String::new();
    out.push_str(
        "<!-- Generated by `cargo xtask docs` from the clap definition in \
         crates/helia-cli/src/lib.rs. Do not edit. -->\n\n\
         # Command line reference\n\n\
         Every subcommand also accepts `-h` and `--help`; `helia` itself also \
         accepts `-V` and `--version`. Exit status is 0 on success and 1 on \
         any error, with the message on standard error.\n\n",
    );
    command(&mut out, &root, 2);
    out
}

fn command(out: &mut String, cmd: &clap::Command, level: usize) {
    let name = cmd.get_bin_name().unwrap_or_else(|| cmd.get_name());
    let _ = writeln!(out, "{} `{name}`\n", "#".repeat(level));
    if let Some(about) = cmd.get_long_about().or_else(|| cmd.get_about()) {
        let _ = writeln!(out, "{about}\n");
    }
    let usage = cmd.clone().render_usage().to_string();
    let usage = usage.trim_start_matches("Usage:").trim();
    let _ = writeln!(out, "```text\n{usage}\n```\n");

    let subs: Vec<_> = cmd
        .get_subcommands()
        .filter(|s| s.get_name() != "help")
        .collect();
    if !subs.is_empty() {
        out.push_str("Subcommands:\n\n");
        for s in &subs {
            let about = s.get_about().map(ToString::to_string).unwrap_or_default();
            let _ = writeln!(out, "* `{}`: {about}", s.get_name());
        }
        out.push('\n');
    }

    let positionals: Vec<_> = cmd.get_arguments().filter(|a| a.is_positional()).collect();
    if !positionals.is_empty() {
        out.push_str("Arguments:\n\n");
        for a in positionals {
            argument(out, a);
        }
        out.push('\n');
    }
    let options: Vec<_> = cmd
        .get_arguments()
        .filter(|a| !a.is_positional() && !matches!(a.get_id().as_str(), "help" | "version"))
        .collect();
    if !options.is_empty() {
        out.push_str("Options:\n\n");
        for a in options {
            argument(out, a);
        }
        out.push('\n');
    }
    for s in subs {
        command(out, s, level + 1);
    }
}

fn argument(out: &mut String, a: &Arg) {
    let value = a
        .get_value_names()
        .map(|v| {
            v.iter()
                .map(|n| format!("<{n}>"))
                .collect::<Vec<_>>()
                .join(" ")
        })
        .unwrap_or_default();
    let head = if a.is_positional() {
        value
    } else {
        let mut flags = Vec::new();
        if let Some(s) = a.get_short() {
            flags.push(format!("-{s}"));
        }
        if let Some(l) = a.get_long() {
            flags.push(format!("--{l}"));
        }
        let flags = flags.join(", ");
        if a.get_action().takes_values() {
            format!("{flags} {value}")
        } else {
            flags
        }
    };
    let help = a
        .get_long_help()
        .or_else(|| a.get_help())
        .map(ToString::to_string)
        .unwrap_or_default();
    let mut line = format!("* `{head}`: {}", help.replace('\n', " "));
    let mut notes = Vec::new();
    if a.is_required_set() {
        notes.push("required".to_owned());
    }
    let defaults: Vec<_> = a
        .get_default_values()
        .iter()
        .map(|d| d.to_string_lossy().into_owned())
        .collect();
    if !defaults.is_empty() && a.get_action().takes_values() {
        notes.push(format!("default `{}`", defaults.join(", ")));
    }
    if a.get_action().takes_values() && a.is_allow_hyphen_values_set() {
        notes.push("may start with a hyphen".to_owned());
    }
    if matches!(a.get_action(), clap::ArgAction::Append) && !help.contains("repeatable") {
        notes.push("repeatable".to_owned());
    }
    if !notes.is_empty() {
        let _ = write!(line, " ({})", notes.join("; "));
    }
    out.push_str(&line);
    out.push('\n');
    let values = a.get_possible_values();
    if !values.is_empty() {
        for v in values.iter().filter(|v| !v.is_hide_set()) {
            let h = v.get_help().map(ToString::to_string).unwrap_or_default();
            let _ = writeln!(
                out,
                "  * `{}`{}",
                v.get_name(),
                if h.is_empty() {
                    String::new()
                } else {
                    format!(": {h}")
                }
            );
        }
    }
}
